'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const stages=[{title:['The iron key','鐵之鑰'],goal:['Recover iron alone on the magnet tray.','在磁鐵托盤上單獨收集鐵。'],mix:['iron','sand']},{title:['The clear channel','清澈水道'],goal:['Keep liquid water in the working vessel, with sand collected separately in the filter.','讓液態水留在操作容器，沙則分開收集在濾紙上。'],mix:['sand','water']},{title:['The crystal seal','晶石封印'],goal:['Recover sand in the filter and solid salt alone in the working vessel. The salt starts dissolved in water.','把沙收集在濾紙上，讓固體鹽單獨留在操作容器。最初，鹽已溶解在水中。'],mix:['sand','salt','water']}];
const names={iron:['Iron','鐵'],sand:['Quartz sand','石英沙'],water:['Water','水'],salt:['Salt','鹽']};
const messages={inspect:['Sample inspected. Choose a tool and observe the result.','觀察完成。選擇工具，看看結果。'],first:['Inspect your sample before using a tool.','使用工具前，先觀察樣本。'],magnet:['Iron moved to the magnet tray. The other material stayed behind.','鐵移到磁鐵托盤，其他材料留在原處。'],none:['Nothing moved. Compare the materials with your earlier observations.','沒有材料移動。把這些材料與之前的觀察比較。'],filter:['Sand stayed in the filter. The liquid passed through into the working vessel.','沙留在濾紙上，液體通過濾紙，流回操作容器。'],dissolved:['Sand stayed in the filter. Water AND dissolved salt passed through together.','沙留在濾紙上。水和已溶解的鹽一起通過濾紙。'],dry:['There is no liquid to pour through this filter. Try a fresh sample if you need one.','沒有液體可以倒入濾紙。如有需要，可以換一份新樣本。'],evaporate:['Water entered the air as vapour. All other materials stayed in the vessel.','水變成水蒸氣進入空氣。其他材料都留在容器裡。'],wrong:['Not separated as requested yet. Compare each container with your mission. You can take a fresh sample and try another order.','還未按任務要求分離。比較各容器和任務目標。可以換新樣本，試試另一個次序。'],solved:['Recovered! A bronze seal opens.','成功分離！一道青銅封印開啟了。'],complete:['Three samples, three discoveries. The crystal cabinet opens!','三份樣本，三次發現。晶石寶櫃打開了！'],fresh:['A fresh sample is ready. Your observations remain in the log.','新樣本準備好了。之前的觀察仍留在紀錄裡。']};
let stage=0,working=[],magnet=[],filter=[],vapor=[],inspected=false,solved=false,saveFailed=false,hintDepth=0,feedback='',history=[];
let observedTarget=OrionProgress.read().hashTarget;
function materialList(a){return a.length?a.map(m=>m==='salt'&&a.includes('water')?t('Dissolved salt','已溶解的鹽'):t(...names[m])).join(' · '):t('Empty','空');}
function hints(){return [[t('Inspect each material. Which one responds to a magnet?','觀察每種材料。哪一種會被磁鐵吸引？'),t('Iron is magnetic; quartz sand is not.','鐵會被磁鐵吸引，石英沙不會。'),t('Inspect, then use the magnet. Present your materials.','先觀察，再使用磁鐵，然後展示材料。')],[t('You need to keep the water as a liquid.','你需要保留液態水。'),t('Sand does not dissolve in water. A paper filter can catch it.','沙不溶於水，濾紙能截留它。'),t('Inspect, then filter. Present your materials.','先觀察，再過濾，然後展示材料。')],[t('The salt travels with the water until the water evaporates.','在水蒸發前，鹽會跟著水一起移動。'),t('Separate the sand while the water is still liquid. Then recover the salt.','趁水仍是液體時，先分離沙，再收集鹽。'),t('Inspect → filter → evaporate → present. If you evaporated first, take a fresh sample.','觀察 → 過濾 → 蒸發 → 展示。如果先蒸發了，請換一份新樣本。')]][stage];}
function render(){document.title=t('The Crystal Alchemist’s Workshop · Orion','晶石煉金工坊 · Orion');$('stageLabel').textContent=t(`SEAL ${stage+1} OF 3 · CHEMISTRY`,`第 ${stage+1} 道封印，共 3 道 · 化學`);$('stageTitle').textContent=t(...stages[stage].title);$('mission').textContent=t(...stages[stage].goal);$('sample').textContent=inspected?t('Original sample: ','原始樣本：')+materialList(stages[stage].mix):t('The sample awaits your inspection.','樣本等你觀察。');$('vessels').innerHTML=[[['Working vessel','操作容器'],working],[['Magnet tray','磁鐵托盤'],magnet],[['Filter paper','濾紙'],filter],[['Air · water vapour','空氣 · 水蒸氣'],vapor]].map(([label,a],i)=>`<section class="vessel"><h3>${t(...label)}</h3><p>${!inspected&&i===0?t('Unexamined sample','未觀察的樣本'):i===3&&a.length?t('Water vapour','水蒸氣'):materialList(a)}</p></section>`).join('');$('controls').hidden=solved;$('feedback').textContent=feedback?t(...messages[feedback]):'';$('next').hidden=!solved||stage===2;$('reward').hidden=!(solved&&stage===2);$('notes').hidden=!(solved&&stage===2);$('scene').classList.toggle('complete',solved&&stage===2);$('seals').textContent=stages.map((_,i)=>i<stage||(i===stage&&solved)?'◆':'◇').join(' ');$('sceneStatus').textContent=solved&&stage===2?t('The crystal answers your discoveries.','晶石回應了你的發現。'):t('Three samples. One forgotten secret.','三份樣本，一個被遺忘的秘密。');$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(s=>`<li>${s}</li>`).join('');$('hint').disabled=hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('log').innerHTML=history.map(k=>`<li>${t(...messages[k])}</li>`).join('')||`<li>${t('Your observations will appear here.','你的觀察會顯示在這裡。')}</li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Please retry saving.','已獲得符印，但儲存失敗。請再次嘗試儲存。'):OrionProgress.has('crystal')?t('Crystal Sigil saved in your collection.','晶石符印已存入你的收藏。'):'';}
function say(k){feedback=k;history.unshift(k);history=history.slice(0,12);render();}
function useTool(tool){if(solved)return;if(!inspected){say('first');return;}if(tool==='magnet'){if(working.includes('iron')){magnet.push('iron');working=working.filter(m=>m!=='iron');say('magnet');}else say('none');}else if(tool==='filter'){if(!working.includes('water'))say('dry');else if(working.includes('sand')){filter.push('sand');working=working.filter(m=>m!=='sand');say(working.includes('salt')?'dissolved':'filter');}else say('none');}else if(tool==='evaporate'){if(working.includes('water')){vapor.push('water');working=working.filter(m=>m!=='water');say('evaporate');}else say('none');}}
function exactly(a,b){return a.length===b.length&&b.every(m=>a.includes(m));}
function check(){if(solved)return;const ok=inspected&&(stage===0?exactly(magnet,['iron'])&&exactly(working,['sand']):stage===1?exactly(filter,['sand'])&&exactly(working,['water']):exactly(filter,['sand'])&&exactly(working,['salt'])&&exactly(vapor,['water']));if(!ok){say('wrong');return;}solved=true;if(stage===2)saveFailed=!OrionProgress.earn('crystal');say(stage===2?'complete':'solved');if(stage<2)$('next').focus();}
function fresh(){working=[...stages[stage].mix];magnet=[];filter=[];vapor=[];inspected=false;solved=false;feedback='';render();}
function resetStage(){hintDepth=0;history=[];saveFailed=false;$('notes').open=false;fresh();}
function resetMission(){stage=0;resetStage();}
$('inspect').onclick=()=>{inspected=true;say('inspect');};for(const tool of ['magnet','filter','evaporate'])$(tool).onclick=()=>useTool(tool);$('check').onclick=check;$('fresh').onclick=()=>{fresh();say('fresh');};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetStage();$('inspect').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{resetMission();$('inspect').focus();};$('retrySave').onclick=()=>{saveFailed=!OrionProgress.earn('crystal');render();};
function syncProgress(){const target=OrionProgress.read().hashTarget,reset=target!==observedTarget&&!OrionProgress.has('crystal');observedTarget=target;if(reset||(solved&&stage===2&&!OrionProgress.has('crystal')&&!saveFailed))resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
